    if (fonts.length > 0) document.body.classList.remove('icons-fallback');
}, () => {});

window.addEventListener('message', ({ data }) => {
    switch (data?.action) {
        case 'open':
            init(data);
            setVisible(app, true);
            break;
        case 'close':
            closeApp();
            break;
        case 'hide':
            cancelFilter();
            setVisible(app, false);
            break;
        case 'show':
            setVisible(app, true);
            scheduleFilter();
            if (activeDialog === vehicleModal) closeVehicleButton.focus();
            break;
        case 'showTestDriveTimer':
            testDriveTimerLabel.textContent = data.label || translate('test_drive', 'Test drive');
            testDriveTimer.style.display = 'block';
            timerCount.textContent = data.time + ' s';
            break;
        case 'updateTestDriveTimer':
            timerCount.textContent = data.time + ' s';
            break;
        case 'hideTestDriveTimer':
            testDriveTimer.style.display = 'none';
            break;
    }
});

document.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape' || !app.classList.contains('visible')) return;

    if (activeDialog === purchaseModal) closeModal();
    else if (activeDialog === testDriveModal) closeTestDriveModal();
    else if (activeDialog === vehicleModal) closeVehicleDetail();
    else if (priceFilter.open) {
        priceFilter.open = false;
        priceFilter.querySelector('summary').focus();
    } else requestClose();
});

closeShopButton.addEventListener('click', requestClose);
closeVehicleButton.addEventListener('click', closeVehicleDetail);
searchInput.addEventListener('input', scheduleFilter);
