grid.addEventListener('click', (event) => {
    const button = event.target.closest('.vehicle-card');
    if (button) openVehicleDetail(vehicleCards[button.dataset.index], button);
});

detailBody.addEventListener('click', (event) => {
    const button = event.target.closest('button[data-action]');
    if (!button || button.disabled) return;

    const { model, label } = detailEntry.car;
    switch (button.dataset.action) {
        case 'buy':
            openBuyModal(model, detailEntry.price, label);
            break;
        case 'preview':
            requestPreview(model);
            break;
        case 'test-drive':
            requestTestDrive(model, label);
            break;
    }
});

app.addEventListener('error', (event) => {
    const image = event.target;
    if (!image.matches('.vehicle-media img')) return;

    const media = image.parentElement;
    if (image.dataset.fallback) {
        media.classList.add('is-illustrative');
        image.src = image.dataset.fallback;
        delete image.dataset.fallback;
    } else {
        media.classList.remove('is-illustrative');
        image.hidden = true;
    }
}, true);

function postNui(action, payload = {}) {
    if (!isFiveM) return;

    fetch('https://' + GetParentResourceName() + '/' + action, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
    });
}

function setVisible(element, visible) {
    element.classList.toggle('visible', visible);
    element.inert = !visible;
}

function closeApp() {
    cancelFilter();
    setVisible(app, false);
    showDialog(null);
    detailTrigger = null;
    detailEntry = null;
    selectedVehicle = null;
    testDriveVehicle = null;
}

function requestClose() {
    postNui('close');
    closeApp();
}

function showDialog(dialog, focusTarget) {
    if (activeDialog) setVisible(activeDialog, false);
    activeDialog = dialog;
    for (const region of catalogRegions) region.inert = Boolean(dialog);
    if (dialog) setVisible(dialog, true);
    focusTarget?.focus({ preventScroll: true });
}

function translate(key, fallback) {
    return uiStrings[key] || fallback;
}

function applyLocale(locale) {
    language = locale?.language === 'cs' ? 'cs' : 'en';
    uiStrings = locale?.ui || {};
    document.documentElement.lang = language;
    document.title = translate('title', 'WQZX Dealership');
    moneyFormatter = new Intl.NumberFormat(language === 'cs' ? 'cs-CZ' : 'en-US');

    for (const [element, defaultText] of localizableText) {
        element.textContent = translate(element.dataset.i18n, defaultText);
    }
    for (const [element, attributes] of localizableAttributes) {
        const label = uiStrings[element.dataset.i18nLabel];
        for (const [name, defaultText] of attributes) {
            element.setAttribute(name, label ? label + (name === 'placeholder' ? '…' : '') : defaultText);
        }
    }
}

function init(data) {
    if (activeDialog) closeApp();
    applyLocale(data.locale);
    currency = data.currency || '$';
    const { playerData } = data;
    document.getElementById('player-name').textContent = playerData.name;
    document.getElementById('player-cash').textContent = formatMoney(playerData.cash);
    document.getElementById('player-bank').textContent = formatMoney(playerData.bank);
    availableColors = data.colors || [];
    testDriveConfig = data.testDrive || { price: 500, time: 60 };

    const dailyDeals = playerData.dailyDeals || {};
    const inventory = playerData.vehicleData || {};
    const categories = [{ id: 'all', label: translate('all_vehicles', 'All vehicles') }];
    vehicleCards = [];
    let maxPrice = 0;
    let hasDailyDeals = false;
    const discountedModels = new Set();

    for (const category of data.categories) {
        if (category.id === 'all') {
            categories[0].label = category.label;
            continue;
        }

        categories.push(category);
        for (const [categoryIndex, car] of (category.cars || []).entries()) {
            const shopData = inventory[car.model];
            const deal = dailyDeals[car.model];
            const discount = shopData?.discount_percent || 0;
            const price = deal?.price ?? car.price - Math.floor(car.price * discount / 100);
            const listedDiscount = discount > 0 && !discountedModels.has(car.model);
            if (listedDiscount) discountedModels.add(car.model);
            const thumbnails = illustrativeImages[category.id];
            vehicleCards.push({
                car,
                category: category.id,
                categoryLabel: car.category || category.label,
                searchText: `${car.label}\n${car.model}`.toLowerCase(),
                imageFallback: thumbnails && thumbnails[categoryIndex % thumbnails.length],
                price,
                deal,
                discount,
                listedDiscount,
                salePaused: shopData?.sales_disabled,
                canBuy: (shopData?.stock ?? 0) > 0 && !shopData?.sales_disabled
            });
            maxPrice = Math.max(maxPrice, car.price);
            hasDailyDeals ||= Boolean(deal);
        }
    }

    if (hasDailyDeals) categories.push({ id: 'daily_deals', label: translate('daily_deals', 'Daily deals') });
    if (discountedModels.size > 0) categories.push({ id: 'discounts', label: translate('discounts', 'Discounts') });

    const buttons = document.createDocumentFragment();
    for (const category of categories) {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'category-btn';
        button.textContent = category.label;
        button.setAttribute('aria-pressed', 'false');
        button.onclick = () => {
            selectCategory(category.id, button);
            scheduleFilter();
        };

        const icon = document.createElement('i');
        icon.className = 'fa-solid ' + (categoryIcons[category.id] || 'fa-car');
        icon.setAttribute('aria-hidden', 'true');
        if (category.id === 'daily_deals') button.classList.add('daily-deals-btn');
        if (category.id === 'discounts') button.classList.add('discount-btn');
        button.prepend(icon);
        buttons.appendChild(button);
    }
    categoriesContainer.replaceChildren(buttons);

    const cards = document.createElement('template');
    cards.innerHTML = vehicleCards.map(renderVehicleCard).join('');
    for (const [index, element] of Array.from(cards.content.children).entries()) {
        vehicleCards[index].element = element;
    }
    searchInput.value = '';
    sortSelect.value = 'price-asc';
    priceFilter.open = false;
    priceRange.max = maxPrice;
    priceRange.value = maxPrice;
    activeCategoryButton = null;
    selectCategory('all', categoriesContainer.firstElementChild);
    sortVehicles();
    cancelFilter();
    filterVehicles();
}

function selectCategory(category, button) {
    if (activeCategoryButton === button) return;
    activeCategoryButton?.classList.remove('active');
    activeCategoryButton?.setAttribute('aria-pressed', 'false');
    activeCategoryButton = button;
    activeCategoryButton.classList.add('active');
    activeCategoryButton.setAttribute('aria-pressed', 'true');
    activeCategory = category;
    selectedCategory.textContent = category === 'all' ? translate('all_short', 'All') : button.textContent;
    grid.scrollTop = 0;
}

function sortVehicles() {
    const sorted = [...vehicleCards];
    if (sortSelect.value === 'name') {
        sorted.sort((a, b) => a.car.label.localeCompare(b.car.label, language));
    } else {
        const direction = sortSelect.value === 'price-desc' ? -1 : 1;
        sorted.sort((a, b) => direction * (a.price - b.price));
    }
    grid.replaceChildren(...sorted.map((entry) => entry.element), emptyResults);
    grid.scrollTop = 0;
}

function scheduleFilter() {
    if (filterFrame === null) filterFrame = requestAnimationFrame(filterVehicles);
}

function cancelFilter() {
    if (filterFrame === null) return;
    cancelAnimationFrame(filterFrame);
    filterFrame = null;
}

function filterVehicles() {
    filterFrame = null;
    const search = searchInput.value.trim().toLowerCase();
    const maxPrice = priceRange.valueAsNumber;
    const rangeMax = Number(priceRange.max);
    priceValue.textContent = formatMoney(maxPrice);
    priceRange.style.setProperty('--range-progress', (rangeMax > 0 ? maxPrice / rangeMax : 0) * 100 + '%');

    let visibleCount = 0;
    for (const entry of vehicleCards) {
        const inCategory = activeCategory === 'all' || activeCategory === entry.category
            || (activeCategory === 'daily_deals' && entry.deal)
            || (activeCategory === 'discounts' && entry.listedDiscount);
        const visible = Boolean(inCategory) && entry.price <= maxPrice && entry.searchText.includes(search);
        if (entry.element.hidden === visible) entry.element.hidden = !visible;
        if (visible) visibleCount++;
    }
    if (resultCount.textContent !== String(visibleCount)) resultCount.textContent = visibleCount;
    emptyResults.hidden = visibleCount > 0;
}

const htmlEntities = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

function escapeHtml(value) {
    return value.replace(/[&<>"']/g, (character) => htmlEntities[character]);
}

function renderPrice(entry) {
    const { car, deal, price, discount } = entry;
    const discountPct = deal?.discount ?? discount;
    if (discountPct <= 0) return `<span class="card-price">${escapeHtml(formatMoney(price))}</span>`;

    return `
        <span class="price-container">
            <span class="old-price">${escapeHtml(formatMoney(deal?.originalPrice ?? car.price))}</span>
            <span class="sale-price">${escapeHtml(formatMoney(price))}</span>
        </span>`;
}

function renderVehicleCard(entry, index) {
    const { car, deal, discount, canBuy, salePaused, imageFallback } = entry;
    const label = escapeHtml(car.label);
    const discountPct = deal?.discount ?? discount;
    const modelImage = car.imageFile ?? (car.hasImage === false ? false : `${car.model.toLowerCase()}.${car.hasImage ? 'webp' : 'png'}`);
    const fallbackImage = imageFallback && `${imageFallback}.png`;
    const isIllustrative = !modelImage && Boolean(fallbackImage);
    const image = modelImage || fallbackImage;
    const src = image ? `src="${vehicleImageBase}${encodeURIComponent(image)}"` : 'hidden';
    const fallback = modelImage && fallbackImage && fallbackImage !== modelImage
        ? `data-fallback="${vehicleImageBase}${encodeURIComponent(fallbackImage)}"`
        : '';
    const availability = canBuy ? translate('in_stock', 'In stock')
        : salePaused ? translate('sales_paused', 'Sales paused') : translate('sold_out', 'Sold out');
    const badge = discountPct > 0
        ? `<span class="sale-badge${deal ? '' : ' inventory-sale'}">-${discountPct}%</span>`
        : '';

    return `
        <button type="button" class="vehicle-card" data-index="${index}" aria-haspopup="dialog"
            aria-labelledby="vehicle-name-${index}" aria-describedby="vehicle-status-${index} vehicle-price-${index}">
            <span class="vehicle-media${isIllustrative ? ' is-illustrative' : ''}">
                <img ${src} alt="" loading="lazy" decoding="async" ${fallback}>
                <span class="illustrative-label">${escapeHtml(translate('sample_photo', 'Illustrative photo'))}</span>
            </span>
            <span class="card-badges">${badge}<span class="class-badge">${escapeHtml(entry.categoryLabel)}</span></span>
            <span class="card-info">
                <span class="card-status${canBuy ? '' : ' unavailable'}" id="vehicle-status-${index}">${escapeHtml(availability)}</span>
                <span class="card-name" id="vehicle-name-${index}">${label}</span>
                <span id="vehicle-price-${index}">${renderPrice(entry)}</span>
            </span>
        </button>`;
}

function openVehicleDetail(entry, trigger) {
    detailEntry = entry;
    detailTrigger = trigger;
    document.getElementById('vehicle-detail-title').textContent = entry.car.label;

    const { car, canBuy, salePaused } = entry;
    const testDriveLabel = escapeHtml(testDriveConfig.label || translate('test_drive', 'Test drive'));
    const speed = car.speed || 180;
    const acceleration = car.accel || 0.35;
    const speedPct = Math.min(speed / 260 * 100, 100);
    const accelPct = Math.min(acceleration / 0.5 * 100, 100);

    const buyText = canBuy ? translate('buy', 'Buy')
        : salePaused ? translate('sales_paused', 'Sales paused') : translate('sold_out', 'Sold out');
    const buyIcon = canBuy ? 'fa-cart-shopping' : salePaused ? 'fa-ban' : 'fa-box';

    detailBody.innerHTML = `
            ${renderPrice(entry)}
            <div class="card-details">
                <span><i class="fa-solid fa-users" aria-hidden="true"></i> ${car.seats || 2} ${escapeHtml(translate('seats', 'Seats'))}</span>
                <span><i class="fa-solid fa-car" aria-hidden="true"></i> ${escapeHtml(entry.categoryLabel)}</span>
            </div>
            <div class="stats">
                <div class="stat-row">
                    <div class="stat-header"><span>${escapeHtml(translate('speed', 'Speed'))}</span> <span>${speed} KM/H</span></div>
                    <div class="bar-bg"><div class="bar-fill" style="width: ${speedPct}%; background: ${getBarColor(speedPct)}"></div></div>
                </div>
                <div class="stat-row">
                    <div class="stat-header"><span>${escapeHtml(translate('acceleration', 'Acceleration'))}</span> <span>${Math.round(accelPct)}%</span></div>
                    <div class="bar-bg"><div class="bar-fill" style="width: ${accelPct}%; background: ${getBarColor(accelPct)}"></div></div>
                </div>
            </div>
            <div class="card-actions">
                <button type="button" class="btn-buy" data-action="buy" ${canBuy ? '' : 'disabled'}><i class="fa-solid ${buyIcon}" aria-hidden="true"></i> ${escapeHtml(buyText)}</button>
                <button type="button" class="btn-view" data-action="preview"><i class="fa-solid fa-eye" aria-hidden="true"></i> ${escapeHtml(translate('preview', 'Preview'))}</button>
                <button type="button" class="btn-test" data-action="test-drive"><i class="fa-solid fa-stopwatch" aria-hidden="true"></i> ${testDriveLabel}</button>
            </div>`;

    const media = trigger.querySelector('.vehicle-media').cloneNode(true);
    media.querySelector('img').loading = 'eager';
    detailBody.prepend(media);
    showDialog(vehicleModal, closeVehicleButton);
}

function closeVehicleDetail() {
    showDialog(null, detailTrigger);
    detailEntry = null;
    detailTrigger = null;
}

function getBarColor(pct) {
    if (pct < 40) return '#e74c3c';
    if (pct < 70) return '#f1c40f';
    return '#2ecc71';
}

function openBuyModal(model, price, label) {
    selectedVehicle = { model, price, label };
    
    document.getElementById('modal-veh-name').innerText = label;
    document.getElementById('modal-veh-price').innerText = formatMoney(price);
    
    const colorContainer = document.getElementById('color-options');
    colorContainer.innerHTML = '';
    
    selectedColorIndex = availableColors.length > 0 ? availableColors[0].index : 0;

    availableColors.forEach((col, idx) => {
        const circle = document.createElement('button');
        circle.type = 'button';
        circle.className = 'color-circle';
        circle.style.backgroundColor = col.hex;
        circle.title = col.label;
        circle.setAttribute('aria-label', col.label);
        circle.setAttribute('aria-pressed', String(idx === 0));
        
        if (idx === 0) circle.classList.add('selected');

        circle.onclick = () => {
            const current = colorContainer.querySelector('.selected');
            current?.classList.remove('selected');
            current?.setAttribute('aria-pressed', 'false');
            circle.classList.add('selected');
            circle.setAttribute('aria-pressed', 'true');
            selectedColorIndex = col.index;
        };

        colorContainer.appendChild(circle);
    });

    showDialog(purchaseModal, colorContainer.firstElementChild || purchaseModal.querySelector('.modal-btn'));
}

function closeModal() {
    selectedVehicle = null;
    showDialog(vehicleModal, detailBody.querySelector('.btn-buy'));
}

function requestTestDrive(model, label) {
    testDriveVehicle = { model, label };
    testDriveTitle.textContent = testDriveConfig.label || translate('test_drive', 'Test drive');
    document.getElementById('td-veh-name').innerText = label;
    document.getElementById('td-price').innerText = testDriveConfig.price === 0 ? translate('free', 'Free') : formatMoney(testDriveConfig.price);
    document.getElementById('td-time').innerText = testDriveConfig.time + ' s';

    const locContainer = document.getElementById('td-locations');
    locContainer.innerHTML = '';
    selectedLocationIndex = 1; 

    if (testDriveConfig.locations && testDriveConfig.locations.length > 0) {
        testDriveConfig.locations.forEach((loc, index) => {
            const actualIndex = index + 1;
            const btn = document.createElement('button');
            btn.type = 'button';
            btn.className = 'location-option';
            if (actualIndex === 1) btn.classList.add('selected');
            btn.setAttribute('aria-pressed', String(actualIndex === 1));

            const icon = document.createElement('i');
            icon.className = loc.icon;
            icon.setAttribute('aria-hidden', 'true');
            btn.append(icon, loc.label);
            
            btn.onclick = () => {
                const current = locContainer.querySelector('.selected');
                current?.classList.remove('selected');
                current?.setAttribute('aria-pressed', 'false');
                btn.classList.add('selected');
                btn.setAttribute('aria-pressed', 'true');
                selectedLocationIndex = actualIndex;
            };
            locContainer.appendChild(btn);
        });
    }
    showDialog(testDriveModal, locContainer.firstElementChild || testDriveModal.querySelector('.modal-btn'));
}

function closeTestDriveModal() {
    testDriveVehicle = null;
    showDialog(vehicleModal, detailBody.querySelector('.btn-test'));
}

function confirmTestDrive() {
    if (!testDriveVehicle) return;
    postNui('testDrive', { model: testDriveVehicle.model, locationIndex: selectedLocationIndex });
    closeTestDriveModal();
}

function confirmBuy(payment) {
    if (!selectedVehicle) return;
    postNui('buy', {
        model: selectedVehicle.model,
        price: selectedVehicle.price,
        label: selectedVehicle.label,
        payment: payment,
        color: selectedColorIndex
    });
    closeModal();
}

function requestPreview(model) {
    postNui('preview', { model: model });
}

function formatMoney(num) {
    const amount = moneyFormatter.format(num);
    return language === 'cs' ? `${amount} ${currency}` : `${currency}${amount}`;
}

